// spec: specs/ui-general.md §7 · кейс .qa/tests/ui-general/ui-12-dashboard-period-persists.md
// seed: tests/seed.admin.spec.ts
// #6f3c9b (עבר QA 21.10): выбранный период дашборда хранится в адресе (/dashboard?period=1|7|90) и переживает обновление;
// 30 дней — по умолчанию, без параметра; невалидный параметр → 30. Только чтение.
// + #279e07 (backfill 2026-10-25, кейс ui-13): «היום» — первый вариант перед 7/30/90; при «היום» карточка «הכנסות» сравнивает
// «לעומת אתמול כולו» (если вчера были поступления; при вчера = 0 — «אין תקופה קודמת להשוואה», решается по ответу rpc/dashboard_metrics
// revenue_prev). «חוב פתוח» по периоду не фильтруется — норма (решение пользователя 18.10), не проверяется.
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const period = (page: Page) => page.getByRole('combobox', { name: 'תקופה' });
const chart = (page: Page) => page.getByRole('img', { name: /^הכנסות לאורך / });

async function openDashboard(page: Page, query = '') {
  await page.goto(`/dashboard${query}`);
  await expect(page.getByRole('heading', { level: 1, name: 'לוח בקרה' })).toBeVisible({ timeout: 30_000 });
  await expect(page.getByText('חוב פתוח', { exact: true })).toBeVisible({ timeout: 30_000 });
}

const CASES = [
  { label: 'היום', value: '1' },
  { label: '7 הימים האחרונים', value: '7' },
  { label: '90 הימים האחרונים', value: '90' },
];

test.describe('ui-general — לוח בקרה: התקופה נשמרת אחרי רענון (#6f3c9b)', () => {
  for (const c of CASES) {
    test(`בחירת «${c.label}» → ?period=${c.value}, אחרי רענון הבחירה נשארת #6f3c9b @desktop @prod-safe`, async ({ page }) => {
      await openDashboard(page);
      await expect(period(page)).toHaveValue('30');
      await period(page).selectOption({ label: c.label });
      await expect(page).toHaveURL(new RegExp(`/dashboard\\?period=${c.value}$`));
      await page.reload();
      await expect(page.getByText('חוב פתוח', { exact: true })).toBeVisible({ timeout: 30_000 });
      await expect(page).toHaveURL(new RegExp(`/dashboard\\?period=${c.value}$`));
      await expect(period(page)).toHaveValue(c.value);
      await expect(period(page).locator('option:checked')).toHaveText(c.label);
      if (c.value !== '1') await expect(chart(page)).toHaveAccessibleName(new RegExp(`^הכנסות לאורך ${c.value} ימים`));
    });
  }

  test('חזרה ל«30 הימים האחרונים» — בלי פרמטר בכתובת, אחרי רענון 30 #6f3c9b @desktop @prod-safe', async ({ page }) => {
    await openDashboard(page, '?period=7');
    await expect(period(page)).toHaveValue('7');
    await period(page).selectOption({ label: '30 הימים האחרונים' });
    await expect(page).toHaveURL(/\/dashboard$/);
    await page.reload();
    await expect(page.getByText('חוב פתוח', { exact: true })).toBeVisible({ timeout: 30_000 });
    await expect(period(page)).toHaveValue('30');
    await expect(chart(page)).toHaveAccessibleName(/^הכנסות לאורך 30 ימים/);
  });

  test('פרמטר לא תקין (?period=abc) — מוצג 30 ימים, הדף לא נופל #6f3c9b @desktop @prod-safe', async ({ page }) => {
    await openDashboard(page, '?period=abc');
    await expect(period(page)).toHaveValue('30');
    await expect(period(page).locator('option:checked')).toHaveText('30 הימים האחרונים');
    await expect(chart(page)).toHaveAccessibleName(/^הכנסות לאורך 30 ימים/);
  });

  test('«היום» ראשונה לפני 7/30/90; ב«היום» ההכנסות מושוות «לעומת אתמול כולו»; 7/30/90 נשארו #279e07 @desktop @prod-safe', async ({ page }) => {
    await openDashboard(page);
    const options = period(page).locator('option');
    await expect(options).toHaveText(['היום', '7 הימים האחרונים', '30 הימים האחרונים', '90 הימים האחרונים']);
    expect(await options.evaluateAll((els) => els.map((e) => (e as HTMLOptionElement).value))).toEqual(['1', '7', '30', '90']);

    const [res] = await Promise.all([
      page.waitForResponse((r) => r.url().includes('/rpc/dashboard_metrics') && /"p_days":\s*1\b/.test(r.request().postData() ?? ''), { timeout: 30_000 }),
      period(page).selectOption({ label: 'היום' }),
    ]);
    const m = (await res.json()) as { revenue_prev?: number | string };
    await expect(chart(page)).toHaveAccessibleName(/^הכנסות היום, לעומת אתמול/);
    if (Number(m.revenue_prev) > 0) {
      await expect(page.getByText('לעומת אתמול כולו')).toBeVisible();
    } else {
      // вчера поступлений не было — сравнивать не с чем
      await expect(page.getByText('אין תקופה קודמת להשוואה')).toBeVisible();
    }

    for (const c of [{ v: '7', l: '7 הימים האחרונים' }, { v: '30', l: '30 הימים האחרונים' }, { v: '90', l: '90 הימים האחרונים' }]) {
      await period(page).selectOption({ label: c.l });
      await expect(chart(page)).toHaveAccessibleName(new RegExp(`^הכנסות לאורך ${c.v} ימים`), { timeout: 30_000 });
      await expect(page.getByText('לעומת אתמול כולו'), `«${c.l}» — без сравнения со вчера`).toHaveCount(0);
    }
  });
});
